(() => {
  'use strict';
  if(document.getElementById('sofra-assistant'))return;
  const host=document.createElement('aside');host.id='sofra-assistant';host.setAttribute('aria-label','Sofra Asistanı');
  host.innerHTML=`<section id="sa-panel" role="dialog" aria-labelledby="sa-title" hidden><header id="sa-header"><span id="sa-avatar" aria-hidden="true">✦</span><div><strong id="sa-title">Sofra Asistanı</strong><small>Birlikte aradığını bulalım.</small></div><button id="sa-close" type="button" aria-label="Asistanı kapat">×</button></header><div id="sa-log" role="log" aria-label="Sohbet" aria-live="polite" aria-relevant="additions"></div><div id="sa-quick" aria-label="Hızlı sorular"><button type="button" data-sa-prompt="Tarif bul">Tarif bul</button><button type="button" data-sa-prompt="Pratik yemek öner">Pratik yemek</button><button type="button" data-sa-prompt="Makaleleri göster">Makaleler</button><button type="button" data-sa-prompt="Alışveriş listem nerede?">Listem nerede?</button></div><form id="sa-form"><label for="sa-input" hidden>Ne arıyorsun?</label><input id="sa-input" maxlength="500" placeholder="Bir tarif veya konu yaz…" autocomplete="off"><button id="sa-send" type="submit" aria-label="Gönder">↑</button></form><p id="sa-status">Site rehberi aktif · Yapay zekâ bağlantısı henüz kurulmadı.</p></section><button id="sa-launch" type="button" aria-controls="sa-panel" aria-expanded="false"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" aria-hidden="true"><path d="M20 11.5a8 8 0 0 1-8 8H5l-4 3v-10a9 9 0 0 1 19-1Z"/><path d="m12 5 1.2 3.8L17 10l-3.8 1.2L12 15l-1.2-3.8L7 10l3.8-1.2Z"/></svg><span>Sofra Asistanı</span></button>`;
  document.body.append(host);
  const $=s=>host.querySelector(s),panel=$('#sa-panel'),launch=$('#sa-launch'),input=$('#sa-input'),log=$('#sa-log');
  const recipes=[{id:0,name:'Mercimek çorbası',time:35,tags:['mercimek','çorba','corba','havuç','havuc','soğan','sogan']},{id:1,name:'Domatesli makarna',time:20,tags:['makarna','domates','pratik','hızlı','hizli']},{id:2,name:'Zeytinyağlı taze fasulye',time:45,tags:['fasulye','sebze','zeytinyağlı','zeytinyagli','domates','soğan']}];
  const readings=[{slug:'bitkisel-beslenme',name:'Bitkisel beslenme: tabağın ötesinde bir fikir',tags:['bitkisel','protein','beslenme']},{slug:'baklagil-hazirlama',name:'Baklagilleri hazırlarken neler değişir?',tags:['baklagil','ıslatma','islatma','pişirme']},{slug:'surdurulebilir-mutfak',name:'Sürdürülebilir mutfak alışverişten başlar',tags:['sürdürülebilir','surdurulebilir','israf','mutfak']},{slug:'gidanin-gercek-maliyeti',name:'Bir gıdanın değeri etiket fiyatından ibaret mi?',tags:['maliyet','fiyat','gıda','gida']}];
  function toggle(open){panel.hidden=!open;launch.setAttribute('aria-expanded',String(open));if(open)input.focus();else launch.focus();}
  launch.addEventListener('click',()=>toggle(panel.hidden));$('#sa-close').addEventListener('click',()=>toggle(false));host.addEventListener('keydown',e=>{if(e.key==='Escape'&&!panel.hidden){e.stopPropagation();toggle(false);}});
  function message(text,user=false,links=[]){const bubble=document.createElement('div');bubble.className='sa-message'+(user?' sa-user':'');const p=document.createElement('p');p.textContent=text;bubble.append(p);if(links.length){const list=document.createElement('div');list.className='sa-links';for(const link of links){const node=document.createElement(link.url?'a':'button');node.textContent=link.label;if(link.url)node.href=link.url;else{node.type='button';node.className='sa-action';node.addEventListener('click',()=>navigate(link.action));}list.append(node);}bubble.append(list);}log.append(bubble);while(log.children.length>30)log.firstElementChild.remove();log.scrollTop=log.scrollHeight;}
  let pending=null,timer;
  function navigate(action){const frame=document.getElementById('codex-visualization');if(!frame){location.href=action.recipe!==undefined?'/?sofra-recipe='+action.recipe:'/?sofra-page='+action.page;return;}if(pending)return;pending=action;frame.contentWindow.postMessage({type:'sofra-assistant-navigate',action},'*');timer=setTimeout(()=>{pending=null;message('Ekran henüz hazır değil. Biraz sonra tekrar deneyebilirsin.');},4000);}
  window.addEventListener('message',e=>{const frame=document.getElementById('codex-visualization');if(e.source!==frame?.contentWindow||e.data?.type!=='sofra-assistant-navigated')return;clearTimeout(timer);pending=null;message('İstediğin ekranı açtım.');if(matchMedia('(max-width:600px)').matches)toggle(false);});
  const recipeLinks=rs=>rs.map(r=>({label:r.name+' · '+r.time+' dk →',action:{recipe:r.id}}));
  const readingLinks=rs=>rs.map(r=>({label:r.name+' ↗',url:'/yazilar/'+r.slug+'/'}));
  function reply(raw){const text=raw.trim();if(!text)return;message(text,true);const q=text.toLocaleLowerCase('tr');
    if(/alerji|hastalık|hastalik|diyabet|tedavi|zayıfla|zayifla/.test(q)){message('Bu rehber kişiye özel sağlık veya diyet önerisi vermez. Tariflerin malzemelerini inceleyebilirsin; alerji ve sağlık durumuna uygunluk için bir uzmana danışmalısın.',recipeLinks(recipes));return;}
    if(/liste|alışveriş|alisveris|sepet/.test(q)){message('Bir tarifi açıp kişi sayısını ayarla, evde olan malzemeleri işaretle ve eksikleri listene ekle. Henüz gerçek markete sipariş gönderilmiyor.',[{label:'Alışveriş listemi aç →',action:{page:'list'}},...recipeLinks(recipes)]);return;}
    if(/makale|yazı|yazi|oku/.test(q)){const matches=readings.filter(r=>r.tags.some(t=>q.includes(t)));message('Uzmanların yayınlarına dayanan kısa okumaları burada bulabilirsin. Her yazıda kaynak bağlantısı var.',readingLinks(matches.length?matches:readings));return;}
    const related=readings.filter(r=>r.tags.some(t=>q.includes(t)));if(related.length){message('Bu konuyla ilgili sitedeki okumalar:',readingLinks(related));return;}
    if(/pratik|hızlı|hizli|dakika|\bdk\b/.test(q)){const match=q.match(/(\d{1,3})\s*(dakika|dk)/);const max=match?Number(match[1]):30;const rs=recipes.filter(r=>r.time<=max);message(rs.length?'Sitede bu süreye uyan tarifler:':'Sitedeki tariflerden hiçbiri bu süreye uymuyor. En kısa seçenek domatesli makarna: 20 dakika.',recipeLinks(rs.length?rs:[recipes[1]]));return;}
    const found=recipes.filter(r=>r.tags.some(t=>q.includes(t)));if(found.length){message('Aramana göre sitede bu tarifleri buldum. Malzemelerinin tamamı evinde olmayabilir; tarifi açıp kontrol edebilirsin.',recipeLinks(found));return;}
    if(/tarif|yemek|pişir|pisir|öner|oner/.test(q)){message('Şu anda sitede bu üç örnek tarif bulunuyor. Birini seçerek detaylarına geçebilirsin.',recipeLinks(recipes));return;}
    if(/merhaba|selam|nasıl|nasil|yardım|yardim/.test(q)){message('Tarif veya malzeme adıyla arama yapabilir, kısa okumaları bulabilir ve alışveriş listene geçebilirsin. Bu sürüm site rehberidir; serbest sorulara yapay zekâ yanıtı henüz veremiyorum.',[{label:'Tarifleri keşfet →',action:{page:'explore'}},...readingLinks(readings.slice(0,1))]);return;}
    message('Bu aramayla eşleşen bir site içeriği bulamadım. “Mercimek”, “20 dakikada yemek” veya “Makaleleri göster” yazabilirsin. Yapay zekâ bağlantısı henüz kurulmadığı için diğer soruları yorumlayamıyorum.',[{label:'Tüm tarifleri aç →',action:{page:'explore'}}]);
  }
  $('#sa-form').addEventListener('submit',e=>{e.preventDefault();reply(input.value.slice(0,500));input.value='';input.focus();});host.querySelectorAll('[data-sa-prompt]').forEach(b=>b.addEventListener('click',()=>reply(b.dataset.saPrompt)));
  message('Merhaba! Sofra’da aradığını bulmana yardımcı olayım. Bir tarif, malzeme veya konu yazabilirsin. Şimdilik site içi arama ve yönlendirme yapıyorum; yapay zekâ yanıtları henüz etkin değil.');
  const frame=document.getElementById('codex-visualization');if(frame){const params=new URLSearchParams(location.search);const recipe=params.get('sofra-recipe'),page=params.get('sofra-page');let action=null;if(['0','1','2'].includes(recipe))action={recipe:Number(recipe)};else if(['home','explore','list'].includes(page))action={page};if(action)frame.addEventListener('load',()=>navigate(action),{once:true});}
})();
